def _canonical_bytes(
    batches: dict[str, dict[str, Any]],
    audit: dict[str, dict[str, Any]],
) -> bytes:
    # Compact UTF-8 JSON, non-ASCII written through, sections in their
    # fixed field order, batches/audit and each batch's items in
    # code-point order, terminated by exactly one newline.
    payload = {
        "version": _VERSION,
        "batches": {},
        "audit": {key: {"key": key,
                        "batch": copy.deepcopy(audit[key]["batch"])}
                  for key in sorted(audit)},
    }
    for key in sorted(batches):
        batch = batches[key]
        ordered_items = [batch["items"][item_key]
                         for item_key in sorted(batch["items"])]
        payload["batches"][key] = {
            "key": batch["key"],
            "owner": batch["owner"],
            "until": batch["until"],
            "lease": batch["lease"],
            "now": batch["now"],
            "status": batch["status"],
            "items": {item_key: copy.deepcopy(item)
                      for item_key, item in
                      ((f"{item['job_id']}\t{item['attempt']}", item)
                       for item in ordered_items)},
        }

